  }
}

/* Feelings tints (foundations.tint): the stroke carries the feeling. Glyphs only, never words. */
.mu-tint-ember { color: var(--mu-tint-ember); } /* joy */
.mu-tint-blush { color: var(--mu-tint-blush); } /* affection */
.mu-tint-tide { color: var(--mu-tint-tide); } /* calm */
.mu-tint-spark { color: var(--mu-tint-spark); } /* wonder */
.mu-tint-graphite { color: var(--mu-tint-graphite); } /* neutral */
.mu-tint-dusk { color: var(--mu-tint-dusk); } /* low */
.mu-tint-iris { color: var(--mu-tint-iris); } /* tension */
/* A tinted glyph is stroke only: its vessel (.v, the feelings circle) is not filled. */
:is(.mu-tint-ember, .mu-tint-blush, .mu-tint-tide, .mu-tint-spark, .mu-tint-graphite, .mu-tint-dusk, .mu-tint-iris) .v:is(.d, .f) { fill-opacity: 0; }
[data-mu-untinted] :is(.mu-tint-ember, .mu-tint-blush, .mu-tint-tide, .mu-tint-spark, .mu-tint-graphite, .mu-tint-dusk, .mu-tint-iris),
[data-mu-untinted]:is(.mu-tint-ember, .mu-tint-blush, .mu-tint-tide, .mu-tint-spark, .mu-tint-graphite, .mu-tint-dusk, .mu-tint-iris) { color: inherit; }
@media (prefers-contrast: more) {
  .mu-tint-ember, .mu-tint-blush, .mu-tint-tide, .mu-tint-spark, .mu-tint-graphite, .mu-tint-dusk, .mu-tint-iris { color: inherit; }
}

/* Frost (tokens.json frost): E2 floating: a surface above other objects blurs what is behind it, lays a translucent fill over the blur, and wears its recipe's shadow stack. */
.mu-frost-strip { background: var(--mu-frost); box-shadow: var(--mu-raise); -webkit-backdrop-filter: var(--mu-backdrop); backdrop-filter: var(--mu-backdrop); } /* A frosted toolbar strip in the colorway (KAMUI-01/02). */
.mu-frost-plate { background: var(--mu-frost-strong); box-shadow: var(--mu-raise); -webkit-backdrop-filter: var(--mu-backdrop); backdrop-filter: var(--mu-backdrop); } /* Floating plates: command palette, menus, popovers, the lens bar and panel (KAMUI-06). */
.mu-frost-graphite { background: var(--mu-frost-graphite-fill); box-shadow: var(--mu-frost-graphite-shadow); -webkit-backdrop-filter: var(--mu-backdrop); backdrop-filter: var(--mu-backdrop); } /* Dense dark chrome that stays graphite in both colorways: the selection tool strip, the medium toolbar, tooltips, the past banner. */
@media (prefers-reduced-transparency: reduce) {
  .mu-frost-strip { background: var(--mu-frost-opaque); -webkit-backdrop-filter: none; backdrop-filter: none; }
  .mu-frost-plate { background: var(--mu-frost-opaque); -webkit-backdrop-filter: none; backdrop-filter: none; }
  .mu-frost-graphite { background: var(--mu-frost-graphite-opaque); -webkit-backdrop-filter: none; backdrop-filter: none; }
}
[data-mu-transparency="reduce"] .mu-frost-strip, .mu-frost-strip[data-mu-transparency="reduce"] { background: var(--mu-frost-opaque); -webkit-backdrop-filter: none; backdrop-filter: none; }
[data-mu-transparency="reduce"] .mu-frost-plate, .mu-frost-plate[data-mu-transparency="reduce"] { background: var(--mu-frost-opaque); -webkit-backdrop-filter: none; backdrop-filter: none; }
[data-mu-transparency="reduce"] .mu-frost-graphite, .mu-frost-graphite[data-mu-transparency="reduce"] { background: var(--mu-frost-graphite-opaque); -webkit-backdrop-filter: none; backdrop-filter: none; }
@media (prefers-contrast: more) {
  .mu-frost-strip { box-shadow: inset 0 0 0 1px var(--mu-contrast-edge), var(--mu-raise); }
  .mu-frost-plate { box-shadow: inset 0 0 0 1px var(--mu-contrast-edge), var(--mu-raise); }
  .mu-frost-graphite { box-shadow: inset 0 0 0 1px rgba(255,255,255,.45), var(--mu-frost-graphite-shadow); }
}
